package com.example.agentic_ai_platform.marketing.dto;
import com.example.agentic_ai_platform.marketing.entity.SeoKeyword; import java.time.Instant; import java.util.UUID;
public record SeoKeywordResponse(UUID id,String keyword,String targetPage,Integer currentRank,Integer previousRank,Integer rankChange,Integer searchVolume,Integer difficulty,String intent,String status,String metaTitle,String metaDescription,String aiRecommendation,Instant createdAt,Instant updatedAt) { public static SeoKeywordResponse from(SeoKeyword k){Integer delta=k.getCurrentRank()==null||k.getPreviousRank()==null?null:k.getPreviousRank()-k.getCurrentRank();return new SeoKeywordResponse(k.getId(),k.getKeyword(),k.getTargetPage(),k.getCurrentRank(),k.getPreviousRank(),delta,k.getSearchVolume(),k.getDifficulty(),k.getIntent(),k.getStatus(),k.getMetaTitle(),k.getMetaDescription(),k.getAiRecommendation(),k.getCreatedAt(),k.getUpdatedAt());} }
